{
  "claims": [
    {
      "claim_text": "git gc --auto returns immediately and runs in the background by default when the system supports it.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage [5] states that gc.autoDetach makes git gc --auto return immediately and run in the background if supported, and the default is true.",
      "citations": [
        {
          "index": 5,
          "quote": "gc.autoDetach: Make git gc --auto return immediately and run in the background if the system supports it. Default is true."
        }
      ]
    },
    {
      "claim_text": "Setting gc.auto to 0 disables automatic packing of loose objects but leaves the gc.autoPackLimit heuristic active.",
      "verdict": "CONTRADICTED",
      "reasoning": "Passage [3] explicitly says setting gc.auto to 0 disables not only automatic packing but also other heuristics such as gc.autoPackLimit. Passage [4] also confirms that setting gc.auto to 0 disables gc.autoPackLimit.",
      "citations": [
        {
          "index": 3,
          "quote": "Setting this to 0 disables not only automatic packing based on the number of loose objects, but also any other heuristic git gc --auto will otherwise use to determine if there’s work to do, such as gc.autoPackLimit."
        },
        {
          "index": 4,
          "quote": "Setting gc.auto to 0 will also disable this."
        }
      ]
    },
    {
      "claim_text": "--prune=now is the safest choice when another process is writing to the repository concurrently.",
      "verdict": "CONTRADICTED",
      "reasoning": "Passage [1] states that --prune=now increases the risk of corruption if another process is writing concurrently, so it is not the safest choice.",
      "citations": [
        {
          "index": 1,
          "quote": "--prune=now prunes loose objects regardless of their age and increases the risk of corruption if another process is writing to the repository concurrently"
        }
      ]
    },
    {
      "claim_text": "By default git gc calls git worktree prune --expire 3.weeks.ago.",
      "verdict": "CONTRADICTED",
      "reasoning": "Passage [10] states that git gc calls git worktree prune --expire 3.months.ago by default, not 3.weeks.ago.",
      "citations": [
        {
          "index": 10,
          "quote": "When git gc is run, it calls git worktree prune --expire 3.months.ago."
        }
      ]
    },
    {
      "claim_text": "If gc.log exists, git gc --auto prints its content and exits with status 1 instead of running, unless the file is older than gc.logExpiry, which defaults to one day.",
      "verdict": "CONTRADICTED",
      "reasoning": "Passage [7] says git gc --auto exits with status zero, not status 1, when gc.log exists and is not older than gc.logExpiry. The default of one day is correct, but the exit status is contradicted.",
      "citations": [
        {
          "index": 7,
          "quote": "If the file gc.log exists, then git gc --auto will print its content and exit with status zero instead of running unless that file is more than gc.logExpiry old. Default is \"1.day\"."
        }
      ]
    },
    {
      "claim_text": "The commit-graph is rewritten on every git gc run by default.",
      "verdict": "CONTRADICTED",
      "reasoning": "Passage [6] says gc.writeCommitGraph, if true, causes gc to rewrite the commit-graph when git-gc is run, and for git gc --auto the commit-graph is updated only if housekeeping is required. It does not say it is rewritten on every run; the default is true but the condition is not 'every run'.",
      "citations": [
        {
          "index": 6,
          "quote": "gc.writeCommitGraph: If true, then gc will rewrite the commit-graph file when git-gc[1] is run. When using git gc --auto the commit-graph will be updated if housekeeping is required. Default is true."
        }
      ]
    },
    {
      "claim_text": "Running git pack-refs makes a repository unclonable over dumb transports such as HTTP by Git versions before 1.5.1.2.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage [8] states exactly that running git pack-refs renders the repository unclonable by Git versions prior to 1.5.1.2 over dumb transports such as HTTP.",
      "citations": [
        {
          "index": 8,
          "quote": "Running git pack-refs in a repository renders it unclonable by Git versions prior to 1.5.1.2 over dumb transports such as HTTP."
        }
      ]
    }
  ]
}
